        return xs[0]
    return min(min_subarray_equations(xs[1:]), min_prefix_equations(xs))

cases = [
    [7], [-8], [3, -5, 2], [5, -10, 7, -3],
    [4, -1, -2, 9, -8], [0, 0, 0], [-1, -2, -3],
    [2, 3, 4, 1, 2, 4],
]
for xs in cases:
    print(xs, 'solution=', module.minSubArraySum(xs),
          'equations=', min_subarray_equations(xs), 'oracle=', oracle(xs),
          'prefixEq=', min_prefix_equations(xs), 'prefixOracle=', prefix_oracle(xs))

checked = 0
for size in range(1, 7):
    for values in product(range(-3, 4), repeat=size):
        xs = list(values)
        assert min_prefix_equations(xs) == prefix_oracle(xs)
        assert min_subarray_equations(xs) == oracle(xs)
        assert module.minSubArraySum(xs) == oracle(xs)
        checked += 1
print('exhaustive_zero_mismatches=', checked)

mutations = {
    'constant_zero': lambda xs: 0,
    'identity_head': lambda xs: xs[0],
    'hardcoded_prompt_examples_else_zero': lambda xs: 1 if xs == [2,3,4,1,2,4] else (-6 if xs == [-1,-2,-3] else 0),
}
for name, bad in mutations.items():
    witness = next(xs for xs in cases if bad(xs) != oracle(xs))
    print('counterfactual_rejected', name, 'witness=', witness,
          'mutated=', bad(witness), 'oracle=', oracle(witness))

def max_prefix_mutation(xs):
    if len(xs) == 1:
        return xs[0]
    return max(xs[0], xs[0] + max_prefix_mutation(xs[1:]))
witness = [3, -5, 2]
print('counterfactual_rejected max_instead_of_min_prefix', 'witness=', witness,
      'mutated=', max_prefix_mutation(witness), 'oraclePrefix=', prefix_oracle(witness))
